import {lamejs} from './vendor/lame.js';
import {gapFrames} from './playlist.js';
export function wavInfo(buffer){const v=new DataView(buffer),text=(p,n)=>String.fromCharCode(...new Uint8Array(buffer,p,n));if(buffer.byteLength<44||text(0,4)!=='RIFF'||text(8,4)!=='WAVE'||text(36,4)!=='data'||v.getUint16(20,true)!==1||v.getUint16(22,true)!==2||v.getUint16(34,true)!==16)throw new Error('合并需要本站生成的双声道 WAV。');const sampleRate=v.getUint32(24,true),bytes=v.getUint32(40,true);if(sampleRate!==44100||bytes%4!==0)throw new Error('歌曲采样格式不一致，无法合并。');return {sampleRate,bytes,frames:bytes/4,duration:bytes/4/sampleRate};}
export function wavHeader(bytes,sampleRate=44100){if(!Number.isSafeInteger(bytes)||bytes<0||bytes>0xffffffff-36||bytes%4)throw new Error('合并音频过大，无法封装 WAV。');const b=new ArrayBuffer(44),v=new DataView(b),s=(p,t)=>{for(let i=0;i<t.length;i++)v.setUint8(p+i,t.charCodeAt(i));};s(0,'RIFF');v.setUint32(4,bytes+36,true);s(8,'WAVE');s(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,2,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*4,true);v.setUint16(32,4,true);v.setUint16(34,16,true);s(36,'data');v.setUint32(40,bytes,true);return b;}
export async function joinWavBlobs(blobs,gaps=[]){if(blobs.length<2)throw new Error('至少需要两首已生成的歌曲。');let total=0;const parts=[];for(const [i,blob] of blobs.entries()){const info=wavInfo(await blob.slice(0,44).arrayBuffer());if(blob.size!==info.bytes+44)throw new Error('单曲音频不完整，请重新生成。');total+=info.bytes;parts.push(blob.slice(44));if(i<blobs.length-1){const bytes=gapFrames(gaps[i]??0)*4;total+=bytes;if(bytes)parts.push(new Uint8Array(bytes));}}return new Blob([wavHeader(total),...parts],{type:'audio/wav'});}
export class ContinuousMp3Encoder{
 constructor(){this.encoder=new lamejs.Mp3Encoder(2,44100,192);this.chunks=[];this.frames=0;this.finished=false;}
 addSilence(seconds){if(this.finished)throw new Error('编码已结束。');const frames=gapFrames(seconds);for(let off=0;off<frames;off+=1152){const zero=new Int16Array(Math.min(1152,frames-off)),chunk=this.encoder.encodeBuffer(zero,zero);if(chunk.length)this.chunks.push(new Uint8Array(chunk));}this.frames+=frames;}
 addWav(buffer,progress=()=>{}){if(this.finished)throw new Error('编码已结束。');const info=wavInfo(buffer),view=new DataView(buffer);if(buffer.byteLength!==44+info.bytes)throw new Error('音频长度不完整。');for(let off=0;off<info.frames;off+=1152){const count=Math.min(1152,info.frames-off),l=new Int16Array(count),r=new Int16Array(count);for(let i=0;i<count;i++){l[i]=view.getInt16(44+(off+i)*4,true);r[i]=view.getInt16(46+(off+i)*4,true);}const chunk=this.encoder.encodeBuffer(l,r);if(chunk.length)this.chunks.push(new Uint8Array(chunk));if(off%46080===0)progress(off/info.frames);}this.frames+=info.frames;progress(1);}
 finish(){if(this.finished)throw new Error('编码已结束。');this.finished=true;const end=this.encoder.flush();if(end.length)this.chunks.push(new Uint8Array(end));const bytes=this.chunks.reduce((s,c)=>s+c.length,0),out=new Uint8Array(bytes);let pos=0;for(const c of this.chunks){out.set(c,pos);pos+=c.length;}this.chunks=[];return out.buffer;}
}
